<?php
namespace App\Http\Controllers;
use App\Models\MediaAsset;use App\Services\GroupAccessResolver;use App\Services\Media\MediaDeliveryService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Gate;
class MediaDeliveryController extends Controller{public function show(Request$r,MediaAsset$mediaAsset,string$variant,GroupAccessResolver$access,MediaDeliveryService$delivery){abort_unless(in_array($variant,['original','optimized','viewer','grid','thumbnail','watermarked','cover_thumbnail','cover_grid','cover_large'],true),404);$group=$mediaAsset->group;abort_unless($group,404);if($mediaAsset->kind==='group_cover'){abort_unless(in_array($variant,['cover_thumbnail','cover_grid','cover_large'],true),404);abort_unless(in_array($mediaAsset->id,[$group->cover_media_asset_id,$group->pending_cover_media_asset_id],true),404);abort_if($r->boolean('download'),403);if($r->user())Gate::forUser($r->user())->authorize('view',$mediaAsset);else abort_unless($access->role($group,null)!=='denied',403);}else{$photo=$mediaAsset->photo;abort_unless($photo&&$photo->group_id===$mediaAsset->group_id,404);if($r->user())Gate::forUser($r->user())->authorize($r->boolean('download')?'download':'view',$mediaAsset);else{$role=$access->role($group,null);$matched=in_array($photo->id,(array)$r->session()->get('guest_face_matches.'.$mediaAsset->group_id,[]),true);abort_unless($role==='anonymous_full'||($role==='anonymous_face_only'&&$matched),403);}if(in_array($variant,['original','optimized','viewer'],true)&&$group->watermark_enabled&&$group->creator->watermarkSetting?->hasLogo()&&!$access->canManage($group,$r->user()))$variant='watermarked';}$record=$mediaAsset->variant($variant);if(!$record&&$variant==='watermarked')$record=$mediaAsset->variants()->where('variant_type','watermarked')->where('state','stale')->latest('version')->first();if(!$record&&$mediaAsset->kind!=='group_cover'&&$variant!=='watermarked')$record=$mediaAsset->variant($variant==='grid'?'thumbnail':'optimized');abort_unless($record&&in_array($record->state,['ready','stale'],true),404);return$delivery->deliver($record,false);}}
